def transform(grid):
    # Copy the marked shape one row up and three columns right.
    out = [row[:] for row in grid]
    marked = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    # The task's marked color can vary across instances; infer the non-background
    # object color as the unique value other than the two background colors.
    if not marked:
        colors = {v for row in grid for v in row}
        obj = next((v for v in colors if v not in (0, 4, 9)), None)
        marked = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == obj]
    for r, c in marked:
        rr, cc = r - 1, c + 3
        if 0 <= rr < len(grid) and 0 <= cc < len(grid[0]):
            out[rr][cc] = grid[r][c]
    return out
